// FIX: Added AI-901 (7 exams total).
// One representative URL per exam to check availability.
// Expand to cover more pages by adding entries here.
const sampleUrls = [
  { exam: 'AI-102', url: 'https://learn.microsoft.com/en-us/azure/ai-services/openai/overview' },
  { exam: 'AZ-104', url: 'https://learn.microsoft.com/en-us/azure/virtual-machines/overview' },
  { exam: 'AZ-305', url: 'https://learn.microsoft.com/en-us/azure/architecture/guide/' },
  { exam: 'GH-300', url: 'https://docs.github.com/en/code-security/getting-started/github-security-features' },
  { exam: 'AB-100', url: 'https://learn.microsoft.com/en-us/azure/machine-learning/overview-what-is-azure-machine-learning' },
  { exam: 'AI-103', url: 'https://learn.microsoft.com/en-us/azure/ai-services/openai/concepts/retrieval-augmented-generation' },
  { exam: 'AI-901', url: 'https://learn.microsoft.com/en-us/azure/ai-services/what-are-ai-services' }
];
return sampleUrls.map(item => ({ json: item }));

const response = $input.first().json;
const urlItem = $('Check One URL at a Time').first().json;
const headers = response.headers || {};
const lastModified = headers['last-modified'] || headers['etag'] || 'unknown';
const statusCode = response.statusCode || 0;
return [{
  json: {
    exam: urlItem.exam,
    url: urlItem.url,
    last_modified: lastModified,
    status_code: statusCode,
    reachable: statusCode >= 200 && statusCode < 400,
    checked_at: new Date().toISOString()
  }
}];

const allResults = $input.all().map(item => item.json);
const unreachable = allResults.filter(r => !r.reachable);
const reachable = allResults.filter(r => r.reachable);
console.log('[CertMasterAI Monitor] ' + reachable.length + ' URLs OK, ' + unreachable.length + ' unreachable');
if (unreachable.length > 0) {
  console.warn('Unreachable: ' + unreachable.map(r => r.url).join(', '));
}
return [{
  json: {
    scan_time: new Date().toISOString(),
    total_checked: allResults.length,
    reachable_count: reachable.length,
    unreachable_count: unreachable.length,
    unreachable_urls: unreachable.map(r => ({ exam: r.exam, url: r.url, status_code: r.status_code })),
    details: allResults
  }
}];

const data = $input.first().json;
console.log('[WF5] All ' + data.total_checked + ' URLs reachable — no alert sent. Scan time: ' + data.scan_time);
return [{ json: { status: 'all_reachable', total_checked: data.total_checked, scan_time: data.scan_time } }];
